    z_t3413_t* boxed = (z_t3413_t*)z_xmalloc(sizeof(z_t3413_t));
    *boxed = z_io_errno_to_IoError(saved_errno);
    result.tag = Z_T4274_TAG_0;
    result.data = boxed;
